function Assert([bool]$ok, [string]$message) { if (-not $ok) { throw "Assertion failed: $message" } }
function Image([int]$width, [int]$height) { [HalconDotNet.HObject]$raw=$null; [HalconDotNet.HOperatorSet]::GenImageConst([ref]$raw,'byte',$width,$height); try { New-Object HalconDotNet.HImage($raw) } finally { $raw.Dispose() } }
function Polygon([double[]]$rows,[double[]]$columns) { [HalconDotNet.HObject]$x=$null; [HalconDotNet.HOperatorSet]::GenContourPolygonXld([ref]$x,[HalconDotNet.HTuple]$rows,[HalconDotNet.HTuple]$columns); $x }
function MultiXld {
    $definitions = @(
        @([double[]]@(0,0,0), [double[]]@(0,5,10)),
        @([double[]]@(0,0,10,0), [double[]]@(0,10,0,0)),
        @([double[]]@(0,0,10,10,0), [double[]]@(0,10,10,0,1)),
        @([double[]]@(0,2,4,6,8,10), [double[]]@(0,3,6,9,12,15))
    )
    [HalconDotNet.HObject]$all=$null; [HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$all)
    foreach($definition in $definitions) { $one=Polygon $definition[0] $definition[1]; [HalconDotNet.HObject]$combined=$null; try { [HalconDotNet.HOperatorSet]::ConcatObj($all,$one,[ref]$combined); $all.Dispose(); $all=$combined; $combined=$null } finally { $one.Dispose(); if($null-ne$combined){$combined.Dispose()} } }
    Write-Output -NoEnumerate $all
}

