[IO.Directory]::CreateDirectory($temp) | Out-Null
$mainType=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true); $serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true); $loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true)
$recordType=$assembly.GetType('HalconWinFormsDemo.Models.VmImageBatchTraceRecord',$true); $itemType=$assembly.GetType('HalconWinFormsDemo.Models.VmImageBatchTraceItem',$true); $layerType=$assembly.GetType('HalconWinFormsDemo.Models.VmBatchTraceLayerSnapshotData',$true); $captureType=$assembly.GetType('HalconWinFormsDemo.Services.VmBatchTraceLayerCapture',$true)
$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true); $metadataType=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true); $snapshotType=$assembly.GetType('HalconWinFormsDemo.Models.VmXldSnapshot',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic'; $all=[Reflection.BindingFlags]'Instance,NonPublic,Public'; $static=[Reflection.BindingFlags]'Static,Public'
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString())); $logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString())); $window=$mainType.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function Field([string]$name){$field=$mainType.GetField($name,$all);if($null-eq$field){throw "Missing field $name"};$value=$field.GetValue($window);Write-Output -NoEnumerate $value}

# A: cross-batch navigation, corrupt-item skip, source/result comparison, layer session controls and exact live restoration.
foreach($name in @('HistoricalPreviousButton','HistoricalNextButton','HistoricalSourceImageButton','HistoricalResultImageButton','HistoricalCompareToggleButton','HistoricalLayerList','DualLeftRoleText','DualRightRoleText')){Assert($null-ne(Field $name)) "$name missing"}
$store=Field 'batchTraceStore'; $records=Field 'batchTraceRecords'; $records.Clear()
function Record([string]$id,[datetime]$started){$r=[Activator]::CreateInstance($recordType);$r.BatchId=$id;$r.RecipeName='S46 Recipe';$r.RecipeFingerprint=('b'*64);$r.StartedAtUtc=$started.ToUniversalTime().ToString('O');$r.CompletedAtUtc=$started.AddMinutes(1).ToUniversalTime().ToString('O');$r.Scope='All';$r.Outcome='OK';$r.AssetsEnabled=$true;$r.Items=New-Object "System.Collections.Generic.List[$itemType]";$r}
function Item([int]$sequence,[string]$name){$i=[Activator]::CreateInstance($itemType);$i.Sequence=$sequence;$i.FileName=$name;$i.FilePath="D:\production\$name";$i.State='OK';$i.ResultCode='OK';$i.ElapsedMilliseconds=10+$sequence;$i}
function SaveAssets($record,$item,[int]$width,[int]$height,[bool]$layers){$source=Image $width $height;$result=Image ($width+20) ($height+10);$captures=New-Object "System.Collections.Generic.List[$captureType]";[HalconDotNet.HObject]$region=$null;[HalconDotNet.HObject]$xld=$null;try{if($layers){[HalconDotNet.HOperatorSet]::GenRectangle1([ref]$region,5,5,40,55);[HalconDotNet.HOperatorSet]::GenContourPolygonXld([ref]$xld,[HalconDotNet.HTuple]@([double]10,30,60),[HalconDotNet.HTuple]@([double]10,70,90));foreach($entry in @(@($region,'Region','Threshold','green'),@($xld,'XLD','Edges','yellow'))){$meta=[Activator]::CreateInstance($layerType);$meta.ToolId=[Guid]::NewGuid().ToString('N');$meta.ToolName=$entry[2];$meta.PortName=$entry[1];$meta.DataType=$entry[1];$meta.Color=$entry[3];$meta.LineWidth=2;$meta.Opacity=80;$meta.IsVisible=$true;$capture=[Activator]::CreateInstance($captureType);$capture.Object=$entry[0];$capture.Metadata=$meta;$captures.Add($capture)}};$store.SaveItemAssets($record,$item,$source,$result,$captures)}finally{$source.Dispose();$result.Dispose();if($null-ne$region){$region.Dispose()};if($null-ne$xld){$xld.Dispose()}}}
$newer=Record 'S46-NEW' ([DateTime]::UtcNow);$first=Item 0 'first.png';$broken=Item 1 'broken.png';$middle=Item 2 'middle.png';foreach($i in @($first,$broken,$middle)){$newer.Items.Add($i)};SaveAssets $newer $first 220 140 $true;SaveAssets $newer $broken 230 150 $false;SaveAssets $newer $middle 240 160 $false
$older=Record 'S46-OLD' ([DateTime]::UtcNow.AddHours(-1));$last=Item 0 'last.png';$older.Items.Add($last);SaveAssets $older $last 260 180 $true
$store.Save($newer)|Out-Null;$store.Save($older)|Out-Null;[IO.File]::WriteAllText((Join-Path $store.DirectoryPath $broken.SourceImageRelativePath),'broken');[IO.File]::WriteAllText((Join-Path $store.DirectoryPath $broken.ResultImageRelativePath),'broken');$records.Add($newer);$records.Add($older)
$live=Image 640 480;$mainType.GetField('currentImage',$private).SetValue($window,$live);$flow=Field 'flowTools';$beforeFlow=$flow.Count;$viewport=Field 'viewport';$comparison=Field 'comparisonViewport';$viewport.SetImageSize(640,480);$comparison.SetImageSize(320,240)
$viewportType=$viewport.GetType();foreach($pair in @(@('row1',30.0),@('column1',40.0),@('row2',329.0),@('column2',439.0))){$viewportType.GetField($pair[0],[Reflection.BindingFlags]'Instance,NonPublic').SetValue($viewport,$pair[1])};$savedPart=@('row1','column1','row2','column2')|ForEach-Object{$viewportType.GetField($_,[Reflection.BindingFlags]'Instance,NonPublic').GetValue($viewport)}
$mainType.GetField('dualImageMode',$private).SetValue($window,$true);$mainType.GetField('maximizedDualImageView',$private).SetValue($window,'Right');(Field 'LinkDualImageViewsCheckBox').IsChecked=$false
$mainType.GetMethod('EnterHistoricalImageMode',$private).Invoke($window,[object[]]@($newer,$first))|Out-Null
Assert([bool]$mainType.GetField('historicalImageMode',$private).GetValue($window)) 'History mode did not start';Assert([object]::ReferenceEquals($live,$mainType.GetField('currentImage',$private).GetValue($window))-and$flow.Count-eq$beforeFlow) 'History entry changed live state';Assert((Field 'HistoricalPreviousButton').IsEnabled-eq$false) 'First history item boundary is wrong';Assert((Field 'HistoricalLayerList').Items.Count-eq2) 'Multiple history layers were not listed'
(Field 'HistoricalCompareToggleButton').IsChecked=$true;$mainType.GetMethod('HistoricalCompareToggleButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;Assert([bool]$mainType.GetField('dualImageMode',$private).GetValue($window)) 'Source/result dual comparison did not start';Assert((Field 'DualInputPortComboBox').Visibility.ToString()-eq'Collapsed'-and(Field 'DualLeftRoleText').Text-ne'输入画面'-and(Field 'DualRightRoleText').Text-ne'输出/预览画面') 'Historical dual roles are not explicit';Assert($comparison.ImageWidth-ne$viewport.ImageWidth) 'Source/result coordinate systems were not isolated'
$panel=New-Object Windows.Forms.Panel;$panel.Width=300;$panel.Height=200;$leftZoom=$comparison.ZoomText;$viewport.ZoomAt([Drawing.Point]::new(100,80),$panel,120);Assert($comparison.ZoomText-eq$leftZoom) 'Independent history view changed the other viewport';(Field 'LinkDualImageViewsCheckBox').IsChecked=$true;$comparison.SynchronizeNormalizedViewFrom($viewport);Assert($comparison.ZoomText-ne$leftZoom) 'Linked history view did not synchronize normalized zoom'
$layers=Field 'historicalLayers';$layers[0].IsVisible=$false;$mainType.GetMethod('HistoricalLayerVisibilityChanged',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;Assert(-not$layers[0].IsVisible-and$layers[1].IsVisible) 'Per-layer history visibility failed';$selectedLayer=$layers[1];$mainType.GetField('historicalIsolatedLayer',$private).SetValue($window,$selectedLayer);foreach($layer in $layers){$layer.IsIsolated=[object]::ReferenceEquals($layer,$selectedLayer)};Assert($selectedLayer.IsIsolated) 'History layer isolate state failed';$mainType.GetMethod('HistoricalClearLayerIsolationButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;Assert($null-eq$mainType.GetField('historicalIsolatedLayer',$private).GetValue($window)-and($layers|Where-Object IsIsolated).Count-eq0) 'History clear-isolate failed';$mainType.GetMethod('HistoricalHideAllLayersButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;Assert(($layers|Where-Object IsVisible).Count-eq0) 'History hide-all failed';$mainType.GetMethod('HistoricalShowAllLayersButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;Assert(($layers|Where-Object IsVisible).Count-eq2) 'History show-all failed'
$mainType.GetMethod('NavigateHistoricalItem',$private).Invoke($window,[object[]]@(1))|Out-Null;Assert([object]::ReferenceEquals($middle,$mainType.GetField('historicalBatchItem',$private).GetValue($window))) 'Unreadable middle item was not skipped';$mainType.GetMethod('NavigateHistoricalItem',$private).Invoke($window,[object[]]@(1))|Out-Null;Assert([object]::ReferenceEquals($older,$mainType.GetField('historicalBatchRecord',$private).GetValue($window))-and[object]::ReferenceEquals($last,$mainType.GetField('historicalBatchItem',$private).GetValue($window))) 'Cross-batch navigation failed';Assert(-not(Field 'HistoricalNextButton').IsEnabled) 'Last history item boundary is wrong';$mainType.GetMethod('NavigateHistoricalItem',$private).Invoke($window,[object[]]@(-1))|Out-Null;Assert([object]::ReferenceEquals($middle,$mainType.GetField('historicalBatchItem',$private).GetValue($window))) 'Reverse cross-batch navigation failed'
$mainType.GetMethod('ExitHistoricalImageMode',$private).Invoke($window,[object[]]@($false))|Out-Null;Assert([object]::ReferenceEquals($live,$mainType.GetField('currentImage',$private).GetValue($window))) 'Return live replaced live image';Assert([bool]$mainType.GetField('dualImageMode',$private).GetValue($window)-and[string]$mainType.GetField('maximizedDualImageView',$private).GetValue($window)-eq'Right'-and-not(Field 'LinkDualImageViewsCheckBox').IsChecked) 'Live dual-view session state was not restored';$restored=@('row1','column1','row2','column2')|ForEach-Object{$viewportType.GetField($_,[Reflection.BindingFlags]'Instance,NonPublic').GetValue($viewport)};Assert((Compare-Object $savedPart $restored).Count-eq0) 'Live zoom/pan part was not restored exactly'

# B: real HALCON point count and endpoint-distance closure filtering, managed output and downstream flow.
$filterKind=[Enum]::Parse($kindType,'XldPointClosureFilter');$inputs=$metadataType.GetMethod('GetInputPorts',$static).Invoke($null,[object[]]@($filterKind));$outputs=$metadataType.GetMethod('GetOutputPorts',$static).Invoke($null,[object[]]@($filterKind));Assert(($inputs|Where-Object{$_.PortName-eq'XLD'-and$_.DataType-eq'XLD'}).Count-eq1) 'Typed XLD input missing';Assert(($outputs|Where-Object{$_.PortName-eq'MeanPointCount'-and$_.DataType-eq'Number'}).Count-eq1-and($outputs|Where-Object{$_.PortName-eq'OriginalIndices'-and$_.DataType-eq'String'}).Count-eq1) 'Typed point/filter outputs missing'
$create=$mainType.GetMethod('CreateFlowTool',$private);$runFilter=$mainType.GetMethod('RunXldPointClosureFilterTool',$private);$execute=$mainType.GetMethod('ExecuteFlowTool',$private);$disposeFlow=$mainType.GetMethod('DisposeFlowTools',$private);$captureRecipe=$mainType.GetMethod('CaptureRecipe',$private)
function Tool([string]$kind,[string]$name){$create.Invoke($window,[object[]]@([Enum]::Parse($kindType,$kind),$name,$true,$null))};function Out($tool,[string]$port){$value=$null;if(-not$tool.TryGetOutputValue($port,[ref]$value)){throw "Missing output $port"};$value};function RunFilter($tool,$xldInput){try{$rawInput=$xldInput.PSObject.BaseObject;$runFilter.Invoke($window,[object[]]@($tool,$rawInput))}catch [Reflection.TargetInvocationException]{throw $_.Exception.InnerException}}
$filter=Tool XldPointClosureFilter 'S46 Point/Closure';$input=MultiXld;try{$filter.Parameters.XldPointMinimum=4;$filter.Parameters.XldPointMaximum=5;$filter.Parameters.XldClosureSelectionMode='ClosedOnly';$filter.Parameters.XldClosureTolerance=1;$result=RunFilter $filter $input;$debugIndices=[string](Out $filter OriginalIndices);$debugOpen=[int](Out $filter InputOpenCount);$debugClosed=[int](Out $filter InputClosedCount);Assert($result.ResultCode-eq'OK'-and$debugIndices-eq'[2,3]'-and$debugOpen-eq2-and$debugClosed-eq2) "Inclusive points or closure tolerance boundary failed: code=$($result.ResultCode), indices=$debugIndices, open=$debugOpen, closed=$debugClosed";Assert([int](Out $filter MinPointCount)-eq4-and[int](Out $filter MaxPointCount)-eq5-and[Math]::Abs([double](Out $filter MeanPointCount)-4.5)-lt.0001) 'Selected point statistics failed';$old=Out $filter XLD;$filter.Parameters.XldClosureTolerance=.999;$result=RunFilter $filter $input;Assert((Out $filter OriginalIndices)-eq'[2]' -and $old.IsDisposed) 'Closure boundary or old managed snapshot release failed';$filter.Parameters.XldPointMinimum=3;$filter.Parameters.XldPointMaximum=6;$filter.Parameters.XldClosureSelectionMode='OpenOnly';$result=RunFilter $filter $input;Assert((Out $filter OriginalIndices)-eq'[1,3,4]'-and[int](Out $filter SelectedOpenCount)-eq3) 'Open-only selection/stable original order failed';[HalconDotNet.HTuple]$count=$null;[HalconDotNet.HOperatorSet]::CountObj($input,[ref]$count);Assert($count.I-eq4) 'Input XLD ownership changed'}finally{$input.Dispose()}
[HalconDotNet.HObject]$empty=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$empty);try{$filter.Parameters.XldPointMinimum=1;$filter.Parameters.XldPointMaximum=10;$filter.Parameters.XldClosureSelectionMode='All';$emptyResult=RunFilter $filter $empty;Assert($emptyResult.ResultCode-eq'NG'-and[int](Out $filter ContourCount)-eq0) 'Empty XLD semantics failed'}finally{$empty.Dispose()}
$filter.Parameters.XldPointMinimum=6;$filter.Parameters.XldPointMaximum=5;Assert(-not[string]::IsNullOrWhiteSpace($filter.Parameters.Validate($filterKind))) 'Invalid point range was accepted';$filter.Parameters.XldPointMinimum=1;$filter.Parameters.XldPointMaximum=5;$filter.Parameters.XldClosureTolerance=-1;Assert(-not[string]::IsNullOrWhiteSpace($filter.Parameters.Validate($filterKind))) 'Negative closure tolerance was accepted';$filter.Parameters.XldClosureTolerance=0;Assert([string]::IsNullOrWhiteSpace($filter.Parameters.Validate($filterKind))) 'Exact closure tolerance zero was rejected'
$disposeFlow.Invoke($window,@())|Out-Null;$flow.Clear();$producer=Tool SubpixelEdgeExtraction 'Producer';$selection=Tool XldPointClosureFilter 'Point Closure Filter';$fit=Tool XldLineFitting 'Fit Selected';$judge=Tool NumericJudge 'Judge Selected Count';$selection.Parameters.XldPointMinimum=3;$selection.Parameters.XldPointMaximum=3;$selection.Parameters.XldClosureSelectionMode='OpenOnly';$selection.Parameters.XldClosureTolerance=0;$selection.SetInputBinding('XLD',$producer.ToolId,'XLD');$fit.SetInputBinding('XLD',$selection.ToolId,'XLD');$judge.SetInputBinding('Value',$selection.ToolId,'ContourCount');$judge.InputToolId=$selection.ToolId;$judge.InputPortName='ContourCount';$judge.NumericLowerLimit=1;$judge.NumericUpperLimit=1;foreach($tool in @($producer,$selection,$fit,$judge)){$flow.Add($tool)}
$source=MultiXld;try{$producer.SetOutputValue('XLD',$snapshotType.GetMethod('Create',$static).Invoke($null,[object[]]@($source.PSObject.BaseObject,$producer.ToolId,$producer.InstanceName,'XLD')));$producer.ResultCode='OK'}finally{$source.Dispose()};foreach($tool in @($selection,$fit,$judge)){$execute.Invoke($window,[object[]]@($tool,'S46 chain'))|Out-Null};Assert($selection.ResultCode-eq'OK'-and$fit.ResultCode-eq'OK'-and$judge.ResultCode-eq'OK') 'XLD/Number downstream chain failed'
(Field 'FlowToolList').SelectedItem=$selection;$mainType.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($selection))|Out-Null;Assert((Field 'DockXldPointClosureFilterPanel').Visibility.ToString()-eq'Visible'-and(Field 'DockXldPointMinimumTextBox').Text-eq'3') 'Dock editor did not synchronize';$recipe=$captureRecipe.Invoke($window,@());$saved=$recipe.ToolFlow|Where-Object ToolType -eq 'XldPointClosureFilter'|Select-Object -First 1;Assert($saved.Parameters.XldPointMinimum-eq3-and$saved.Parameters.XldClosureSelectionMode-eq'OpenOnly'-and$saved.Parameters.XldClosureTolerance-eq0) 'Point/closure parameters were not persisted'
$upstream=Out $producer XLD;$upstream.Dispose();$failed=$false;try{$execute.Invoke($window,[object[]]@($selection,'released upstream'))|Out-Null}catch{$failed=$true};Assert $failed 'Released upstream XLD was accepted'

$mainType.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
Write-Output 'S46 historical navigation/comparison and HALCON XLD point-count/closure filter smoke tests passed.'
